      if (fsFlags === "r+") fsFlags = "w+";  // r+ doesn't truncate, w+ does
    }

    if (flags & O_APPEND) {
      if (fsFlags === "w") fsFlags = "a";
      else if (fsFlags === "w+") fsFlags = "a+";
